    const x = this.baseline.x,
      y = this.baseline.y;
    this.baseline.x = Math.round(x);
    this.baseline.y = Math.round(y);
    this.position = {
      x: pixels(pixels(x) + this.baseline.x),
      y: pixels(pixels(y) + this.baseline.y),
    };
  }
  tick(random: () => number) {
